-- NFL reference data seed (teams + players)
-- Source: ESPN public API. Snapshot: 2026-08-09T05:58:05+00:00
-- Season 2026 (Preseason) | 32 teams | 2968 players
--
-- Idempotent: safe to re-run. Upserts on the ESPN id, never deletes.
-- If you already have an nfl_teams table with a different shape, load these into the
-- staging names below and map columns yourself rather than editing this file.

create extension if not exists pg_trgm;
create extension if not exists unaccent;

create table if not exists nfl_teams (
  id                 uuid primary key default gen_random_uuid(),
  espn_team_id       text not null unique,
  abbreviation       text not null,
  display_name       text not null,
  short_display_name text,
  name               text,
  location           text,
  slug               text,
  conference         text,
  division           text,
  color              text,
  alternate_color    text,
  logo_url           text,
  last_synced_at     timestamptz not null default now()
);

create table if not exists nfl_players (
  id               uuid primary key default gen_random_uuid(),
  espn_athlete_id  text not null unique,
  full_name        text not null,
  first_name       text,
  last_name        text,
  jersey           text,
  position_abbr    text,
  position_name    text,
  position_group   text,
  team_id          uuid references nfl_teams(id) on delete restrict,
  experience_years int,
  is_rookie        boolean generated always as (experience_years = 0) stored,
  status           text,
  headshot_url     text,
  name_is_ambiguous boolean not null default false,
  is_active        boolean not null default true,
  last_synced_at   timestamptz not null default now()
);

-- unaccent() is STABLE, not IMMUTABLE, so it cannot be used directly in a generated
-- column. These immutable wrappers are the supported workaround; the two-argument form
-- pins the dictionary so the result is deterministic.
create or replace function nfl_norm(txt text) returns text
language sql immutable parallel safe as $fn$
  select trim(regexp_replace(lower(unaccent('unaccent', coalesce(txt,''))), '[^a-z0-9]+', ' ', 'g'))
$fn$;

create or replace function nfl_squash(txt text) returns text
language sql immutable parallel safe as $fn$
  select regexp_replace(lower(unaccent('unaccent', coalesce(txt,''))), '[^a-z0-9]+', '', 'g')
$fn$;

-- Indexes four forms so all of these match: "mahomes", "Mahomes, Patrick",
-- "o'cyrus", "ocyrus", "van pran-granger", "vanpran".
alter table nfl_players
  add column if not exists search_text text
  generated always as (
    nfl_norm(full_name) || ' ' ||
    nfl_norm(coalesce(last_name,'') || ' ' || coalesce(first_name,'')) || ' ' ||
    nfl_squash(full_name) || ' ' ||
    nfl_squash(coalesce(last_name,'') || coalesce(first_name,''))
  ) stored;

create index if not exists nfl_players_search_trgm on nfl_players using gin (search_text gin_trgm_ops);
create index if not exists nfl_players_team        on nfl_players (team_id);
create index if not exists nfl_players_position    on nfl_players (position_abbr);
create index if not exists nfl_players_rookie      on nfl_players (is_rookie) where is_rookie;

create table if not exists nfl_coaches (
  id                uuid primary key default gen_random_uuid(),
  espn_coach_id     text not null unique,
  first_name        text,
  last_name         text,
  full_name         text not null,
  team_id           uuid references nfl_teams(id) on delete restrict,
  experience_years  int,
  headshot_url      text,
  name_is_ambiguous boolean not null default false,
  is_active         boolean not null default true,
  last_synced_at    timestamptz not null default now()
);

create index if not exists nfl_coaches_team on nfl_coaches (team_id);

